379	func FetchMetadataBranch(ctx context.Context) error {
380		branchName := paths.MetadataBranchName
381	
382		// Use git CLI for fetch (go-git's fetch can be tricky with auth)
383		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
