390			if ctx.Err() == context.DeadlineExceeded {
391				return errors.New("fetch timed out after 2 minutes")
392			}
393			return fmt.Errorf("failed to fetch %s from origin: %s: %w", branchName, strings.TrimSpace(string(output)), err)
394		}
395	
396		repo, err := openRepository(ctx)
397		if err != nil {
398			return fmt.Errorf("failed to open repository: %w", err)
399		}
400	
401		// Get the remote branch reference
402		remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
403		if err != nil {
404			return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
405		}
